for mm,name,rows in [('09','September',rows09),('10','October',rows10)]:
 Q=[]
 for line in rows.splitlines():
  idx,q,correct,wrong=line.split('~');ref='E6-25'+mm+'-'+idx.zfill(3);n=N[ref];o=[correct]+wrong.split('|');random.Random(ref).shuffle(o)
  Q.append(dict(id=name[:3].upper()+f'-{len(Q)+1:02}',question=q,options=o,answer=o.index(correct),explanation=n['static_link']+' '+n['analysis'][0]+' Caution: '+n['trap'],ref=ref))
 assert len(Q)==30
 (R/'data'/f'{name.lower()}-mcqs.json').write_text(json.dumps(Q,ensure_ascii=False,indent=2)+'\n')
 for_frameworks={'09':[2,7,10,18,22,25,27,32],'10':[8,9,13,17,19,20,27,33]}
 lines=['# '+name+' 2025 · Original Mains frameworks','','Eight answer plans; not model predictions or official marking schemes. Separate sourced facts from original analysis. Historical snapshots require current legal/status checks.']
 for i in for_frameworks[mm]:
  n=N['E6-25'+mm+'-'+str(i).zfill(3)]
  lines+=['','## '+n['mains'],'','**Study reference:** '+n['id'],'','**Opening:** '+n['static_link'],'','**Dated evidence:** '+n['facts'][0]+' '+n['facts'][1],'','**Core argument:** '+n['analysis'][0],'','**Counterpoint / evidence limit:** '+n['trap'],'','**Implementation lens:** '+n['analysis'][1],'','**Answer structure:** Define the mechanism; use the dated evidence; distinguish formal approval from delivery; examine one distributional and one administrative constraint; propose accountable implementation with measurable outcomes.','', '**Conclusion:** Assess success through verified outcomes and accessible remedies, not announcements alone. State what additional evidence would change the assessment.']
 (R/'volumes'/f'{name}-2025-Mains-Frameworks.md').write_text('\n'.join(lines)+'\n')
print('Added 60 original MCQs and 16 referenced answer frameworks')
